```ts
import type { CartItemView, CartSummary } from '../domain/cart.js';

/** Estrategia de descuento. Añadir tipos nuevos = extender este union. */
export interface DiscountRule {
  code: string;
  type: 'percent' | 'fixed';
  /** % (para 'percent') o céntimos (para 'fixed'). */
  value: number;
  /** Compra mínima en céntimos para poder aplicarlo. */
  minSubtotalCents?: number;
}

export interface PricingConfig {
  /** Impuesto sobre el importe gravable (0.21 = IVA 21 %). */
  taxRate: number;
  shippingCents: number;
  freeShippingThresholdCents: number;
  /** Códigos activos, indexados en mayúsculas. */
  discounts: Record<string, DiscountRule>;
}

export class PricingService {
  constructor(private readonly config: PricingConfig) {}

  findDiscount(code: string): DiscountRule | null {
    return this.config.discounts[code.trim().toUpperCase()] ?? null;
  }

  /**
   * Calcula el desglose completo. Todos los importes son céntimos enteros y
   * se redondea una sola vez por concepto para que la suma siempre cuadre.
   */
  price(items: CartItemView[], discountCode: string | null): CartSummary {
    const subtotalCents = items.reduce((sum, item) => sum + item.lineTotalCents, 0);

    let discountCents = 0;
    let appliedCode: string | null = null;
    const rule = discountCode ? this.findDiscount(discountCode) : null;
    // Se re-evalúa en cada lectura: si el carrito baja del mínimo, deja de aplicarse.
    if (rule && subtotalCents >= (rule.minSubtotalCents ?? 0)) {
      discountCents =
        rule.type === 'percent'
          ? Math.round((subtotalCents * rule.value) / 100)
          : Math.min(rule.value, subtotalCents);
      appliedCode = rule.code;
    }

    const taxableBase = subtotalCents - discountCents;
    const shippingCents =
      subtotalCents === 0 || taxableBase >= this.config.freeShippingThresholdCents
        ? 0
        : this.config.shippingCents;

    const taxCents = Math.round((taxableBase + shippingCents) * this.config.taxRate);
    const totalCents = taxableBase + shippingCents + taxCents;

    return {
      subtotalCents,
      discountCode: appliedCode,
      discountCents,
      taxRate: this.config.taxRate,
      taxCents,
      shippingCents,
      totalCents,
    };
  }
}
```

**src/services/cart-service.ts** — the core. Let me write it carefully:

```ts
import { randomUUID } from 'node:crypto';
import {
  MAX_QTY_PER_ITEM,
  type Cart,
  type CartItemView,
  type CartView,
} from '../domain/cart.js';
import {
  CartItemNotFoundError,
  CartNotFoundError,
  DiscountMinSubtotalError,
  EmptyCartError,
  InvalidDiscountCodeError,
  InvalidQuantityError,
  OutOfStockError,
  ProductNotFoundError,
} from '../domain/errors.js';
import type { CartRepository, ProductRepository } from '../ports/repositories.js';
import type { PricingService } from './pricing-service.js';

export interface CheckoutResult {
  order: {
    id: string;
    createdAt: string;
    itemCount: number;
    totalCents: number;
  };
  cart: CartView;
}

/**
 * Casos de uso del carrito. No sabe nada de HTTP ni de SQL: solo dominio,
 * puertos y pricing. Se prueba con repositorios en memoria (véase tests/).
 */
export class CartService {
  constructor(
    private readonly carts: CartRepository,
    private readonly products: ProductRepository,
    private readonly pricing: PricingService,
  ) {}

  async createCart(): Promise<CartView> {
    const now = new Date().toISOString();
    const cart: Cart = {
      id: `c_${randomUUID()}`,
      items: [],
      discountCode: null,
      createdAt: now,
      updatedAt: now,
    };
    await this.carts.create(cart);
    return this.buildView(cart);
  }

  async getCart(cartId: string): Promise<CartView> {
    return this.buildView(await this.mustGetCart(cartId));
  }

  /** Añade `quantity` unidades; si el producto ya está, las suma a la línea. */
  async addItem(cartId: string, productId: string, quantity: number): Promise<CartView> {
    this.assertQuantity(quantity);
    const cart = await this.mustGetCart(cartId);
    const product = await this.mustGetProduct(productId);
    const current = cart.items.find((i) => i.productId === productId)?.quantity ?? 0;
    const target = current + quantity;
    if (target > Math.min(product.stock, MAX_QTY_PER_ITEM)) {
      throw new OutOfStockError(product.id, target, Math.min(product.stock, MAX_QTY_PER_ITEM));
    }
    return this.upsertAndSave(cart, productId, target);
  }

  /** Fija la cantidad de una línea (0 = eliminar la línea). */
  async setQuantity(cartId: string, productId: string, quantity: number): Promise<CartView> {
    if (quantity === 0) return this.removeItem(cartId, productId);
    this.assertQuantity(quantity);
    const cart = await this.mustGetCart(cartId);
    if (!cart.items.some((i) => i.productId === productId)) {
      throw new CartItemNotFoundError(productId);
    }
    const product = await this.mustGetProduct(productId);
    if (quantity > product.stock) throw new OutOfStockError(product.id, quantity, product.stock);
    return this.upsertAndSave(cart, productId, quantity);
  }

  async removeItem(cartId: string, productId: string): Promise<CartView> {
    const cart = await this.mustGetCart(cartId);
    const before = cart.items.length;
    cart.items = cart.items.filter((i) => i.productId !== productId);
    if (cart.items.length === before) throw new CartItemNotFoundError(productId);
    return this.save(cart);
  }

  async clearCart(cartId: string): Promise<CartView> {
    const cart = await this.mustGetCart(cartId);
    cart.items = [];
    return this.save(cart);
  }

  async applyDiscount(cartId: string, code: string): Promise<CartView> {
    const cart = await this.mustGetCart(cartId);
    const rule = this.pricing.findDiscount(code);
    if (!rule) throw new InvalidDiscountCodeError(code);
    const subtotalCents = (await this.buildView(cart)).summary.subtotalCents;
    const min = rule.minSubtotalCents ?? 0;
    if (subtotalCents < min) throw new DiscountMinSubtotalError(rule.code, min, subtotalCents);
    cart.discountCode = rule.code;
    return this.save(cart);
  }

  async removeDiscount(cartId: string): Promise<CartView> {
    const cart = await this.mustGetCart(cartId);
    cart.discountCode = null;
    return this.save(cart);
  }

  /**
   * Checkout: re-valida stock, lo descuenta, vacía el carrito y devuelve el
   * resumen del pedido. Si algo falla a mitad, compensa los descuentos ya
   * aplicados (una transacción real sería el siguiente paso: ver README).
   */
  async checkout(cartId: string): Promise<CheckoutResult> {
    const cart = await this.mustGetCart(cartId);
    if (cart.items.length === 0) throw new EmptyCartError();

    const snapshot = await this.buildView(cart);

    const decremented: { productId: string; quantity: number }[] = [];
    for (const item of cart.items) {
      const ok = await this.products.adjustStock(item.productId, -item.quantity);
      if (!ok) {
        for (const done of decremented) {
          await this.products.adjustStock(done.productId, done.quantity);
        }
        const product = await this.products.findById(item.productId);
        if (!product) throw new ProductNotFoundError(item.productId);
        throw new OutOfStockError(product.id, item.quantity, product.stock);
      }
      decremented.push(item);
    }

    cart.items = [];
    cart.discountCode = null;
    const view = await this.save(cart);

    return {
      order: {
        id: `o_${randomUUID()}`,
        createdAt: new Date().toISOString(),
        itemCount: snapshot.itemCount,
        totalCents: snapshot.summary.totalCents,
      },
      cart: view,
    };
  }

  private assertQuantity(quantity: number): void {
    if (!Number.isInteger(quantity) || quantity < 1 || quantity > MAX_QTY_PER_ITEM) {
      throw new InvalidQuantityError(quantity, MAX_QTY_PER_ITEM);
    }
  }

  private async mustGetCart(cartId: string): Promise<Cart> {
    const cart = await this.carts.findById(cartId);
    if (!cart) throw new CartNotFoundError(cartId);
    return cart;
  }

  private async mustGetProduct(productId: string): Promise<Product> — need import type Product.

  private async upsertAndSave(cart: Cart, productId: string, quantity: number): Promise<CartView> {
    const existing = cart.items.find((i) => i.productId === productId);
    if (existing) existing.quantity = quantity;
    else cart.items.push({ productId, quantity });
    return this.save(cart);
  }

  private async save(cart: Cart): Promise<CartView> {
    cart.updatedAt = new Date().toISOString();
    await this.carts.save(cart);
    return this.buildView(cart);
  }

  /** Enriquece los items con datos del catálogo y calcula el desglose. */
  private async buildView(cart: Cart): Promise<CartView> {
    const items: CartItemView[] = [];
    for (const item of cart.items) {
      const product = await this.products.findById(item.productId);
      if (!product) continue; // producto retirado del catálogo: no se muestra
      items.push({
        productId: product.id,
        name: product.name,
        emoji: product.emoji,
        unitPriceCents: product.priceCents,
        quantity: item.quantity,
        lineTotalCents: product.priceCents * item.quantity,
        stock: product.stock,
      });
    }
    const summary = this.pricing.price(items, cart.discountCode);
    return {
      id: cart.id,
      itemCount: items.reduce((sum, item) => sum + item.quantity, 0),
      items,
      summary,
    };
  }
}
```

Wait, in addItem I use `Math.min(product.stock, MAX_QTY_PER_ITEM)` as limit and OutOfStockError with "available" = min(stock, MAX). Slight semantic overload of OUT_OF_STOCK but details include available limit; message says "solicitadas X, disponibles Y". Acceptable. Alternatively throw InvalidQuantityError if the binding constraint is MAX_QTY... nuance not worth it; keep OutOfStock with available = min(stock, MAX).

