/** Valida la FORMA de la petición (transporte). Las reglas de negocio viven en el servicio. */
function requireProductId(body: unknown): string {
  const { productId } = (body ?? {}) as Record<string, unknown>;
  if (typeof productId !== 'string' || productId.trim() === '') {
    throw new RequestValidationError("Se requiere 'productId' (string no vacío)");
  }
  return productId.trim();
}

function requireQuantity(body: unknown, { required }: { required: boolean }): number {
  const { quantity } = (body ?? {}) as Record<string, unknown>;
  if (quantity === undefined && !required) return 1;
  if (typeof quantity !== 'number' || !Number.isSafeInteger(quantity) || quantity < 0 || quantity > 99) {
    throw new RequestValidationError("'quantity' debe ser un entero entre 0 y 99");
  }
  return quantity;
}
