app.js:
```js
const $ = (sel) => document.querySelector(sel);
const els = { grid: $('#product-grid'), panel: $('#cart-panel'), count: $('#cart-count'), toggle: $('#cart-toggle'), toast: $('#toast') };

const eur = new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR' });
const fmt = (cents) => eur.format(cents / 100);

const state = { products: [], cart: null, busy: false };

const CART_KEY = 'tiendadev:cart-id';

async function api(path, { method = 'GET', body } = {}) {
  const res = await fetch(path, {
    method,
    headers: body ? { 'Content-Type': 'application/json' } : {},
    body: body ? JSON.stringify(body) : undefined,
  });
  if (!res.ok) {
    const payload = await res.json().catch(() => null);
    const err = new Error(payload?.error?.message ?? `Error ${res.status}`);
    err.code = payload?.error?.code;
    err.status = res.status;
    throw err;
  }
  return res.status === 204 ? null : res.json();
}

async function ensureCart() {
  const savedId = localStorage.getItem(CART_KEY);
  if (savedId) {
    try { state.cart = await api(`/api/carts/${savedId}`); return; }
    catch (err) { if (err.status !== 404) throw err; }
  }
  state.cart = await api('/api/carts', { method: 'POST' });
  localStorage.setItem(CART_KEY, state.cart.id);
}

async function refreshProducts() {
  const { products } = await api('/api/products');
  state.products = products;
  renderProducts();
}

function renderProducts() {
  els.grid.innerHTML = state.products.map((p) => `
    <article class="product">
      <div class="product-emoji">${p.emoji}</div>
      <h3 class="product-name">${esc(p.name)}</h3>
      <p class="product-desc">${esc(p.description)}</p>
      <div class="product-foot">
        <div>
          <div class="price">${fmt(p.priceCents)}</div>
          <div class="stock ${p.stock === 0 ? 'out' : ''}">${p.stock === 0 ? 'Sin stock' : p.stock + ' uds.'}</div>
        </div>
        <button class="btn" data-add="${p.id}" ${p.stock === 0 ? 'disabled' : ''}>Añadir</button>
      </div>
    </article>
  `).join('');
}

function renderCart() {
  const cart = state.cart;
  if (!cart) return;
  els.count.textContent = cart.itemCount;
  els.count.hidden = cart.itemCount === 0;
  const s = cart.summary;
  const itemsHtml = cart.items.length === 0
    ? `<p class="cart-empty">Tu carrito está vacío.</p>`
    : cart.items.map((i) => `
      <div class="cart-item">
        <div class="cart-item-emoji">${i.emoji}</div>
        <div>
          <div class="cart-item-name">${esc(i.name)}</div>
          <div class="cart-item-unit">${fmt(i.unitPriceCents)} / ud.</div>
          <div class="stepper">
            <button data-dec="${i.productId}" ${i.quantity <= 1 ? '' : ''} aria-label="Restar una unidad">−</button>
            <span class="qty">${i.quantity}</span>
            <button data-inc="${i.productId}" aria-label="Añadir una unidad">+</button>
          </div>
        </div>
        <div style="text-align:right">
          <div class="line-total">${fmt(i.lineTotalCents)}</div>
          <button class="remove" data-remove="${i.productId}" aria-label="Eliminar línea">🗑️</button>
        </div>
      </div>`).join('');
  const discountHtml = s.discountCode
    ? `<div class="discount-applied"><span>✅ ${esc(s.discountCode)}</span><button class="btn ghost small" data-remove-discount>Quitar</button></div>`
    : `<form class="discount-form" id="discount-form">
         <input name="code" placeholder="Código promocional" autocomplete="off" required />
         <button class="btn secondary" type="submit">Aplicar</button>
       </form>`;
  els.panel.innerHTML = `
    <h2 class="cart-title">🧺 Tu carrito <button class="cart-close" id="cart-close" aria-label="Cerrar carrito">✕</button></h2>
    ${itemsHtml}
    ${discountHtml}
    <div class="summary">
      <div class="summary-row"><span>Subtotal</span><span>${fmt(s.subtotalCents)}</span></div>
      ${s.discountCents > 0 ? `<div class="summary-row discount"><span>Descuento ${esc(s.discountCode ?? '')}</span><span>−${fmt(s.discountCents)}</span></div>` : ''}
      <div class="summary-row"><span>Envío</span><span>${s.shippingCents === 0 ? 'Gratis' : fmt(s.shippingCents)}</span></div>
      <div class="summary-row"><span>IVA (${Math.round(s.taxRate * 100)} %)</span><span>${fmt(s.taxCents)}</span></div>
      <div class="summary-row total"><span>Total</span><span>${fmt(s.totalCents)}</span></div>
    </div>
    <button class="btn" id="checkout" ${cart.items.length === 0 || state.busy ? 'disabled' : ''}>Tramitar pedido</button>
  `;
  // listeners...
}
```

