    "express": "^5.0.0"
  },
  "devDependencies": {
    "@types/express": "^5.0.0",
    "@types/node": "^22.0.0",
    "tsx": "^4.19.0",
    "typescript": "^5.6.0",
    "vitest": "^3.0.0"
  }
}

/**
 * Entidad de catálogo.
 *
 * Escalabilidad: los precios se guardan en CÉNTIMOS (enteros) para evitar
 * errores de coma flotante. Operar con dinero en euros como `number` es un
 * bug clásico (0.1 + 0.2 !== 0.3).
 */
export interface Product {
  id: string;
  name: string;
  description: string;
  /** Precio por unidad en céntimos (1234 = 12,34 €). */
  priceCents: number;
  /** Moneda ISO 4217. */
  currency: string;
  /** Unidades disponibles. */
  stock: number;
  category: string;
  /** Emoji decorativo para la UI de demostración. */
  emoji: string;
}

/**
 * Agregado raíz del carrito.
 *
 * El carrito SOLO guarda referencias (`productId` + `quantity`): los precios y
 * nombres se resuelven contra el catálogo en el momento de leerlo. Así un cambio
 * de precio se refleja siempre con datos frescos y nunca se confía en precios
 * enviados por el cliente.
 */
export interface CartItem {
  productId: string;
  quantity: number;
}

export interface Cart {
  id: string;
  items: CartItem[];
  /** Código de descuento guardado (o null). Se re-evalúa en cada lectura. */
  discountCode: string | null;
  createdAt: string;
  updatedAt: string;
}

/** Regla de negocio: unidades máximas por línea. */
export const MAX_QTY_PER_ITEM = 99;

/** Item enriquecido con datos del catálogo, para las respuestas de la API. */
export interface CartItemView {
  productId: string;
  name: string;
  emoji: string;
  unitPriceCents: number;
  quantity: number;
  lineTotalCents: number;
  stock: number;
}

/** Desglose de precios calculado por PricingService. */
export interface CartSummary {
  subtotalCents: number;
  discountCode: string | null;
  discountCents: number;
  taxRate: number;
  taxCents: number;
  shippingCents: number;
  totalCents: number;
}

/** Representación del carrito que devuelve la API. */
export interface CartView {
  id: string;
  itemCount: number;
  items: CartItemView[];
  summary: CartSummary;
}

/**
 * Errores de dominio.
 *
 * Cada error sabe su `code` (estable, para clientes de la API) y su estado
 * HTTP. La traducción error → respuesta HTTP vive en UN único sitio (el
 * middleware de error), así que añadir casos nuevos no obliga a tocar la capa
 * HTTP ni a buscar `res.status(...)` por todas partes.
 */
export class DomainError extends Error {
  constructor(
    message: string,
    readonly code: string,
    readonly httpStatus: number,
    readonly details?: unknown,
  ) {
    super(message);
    this.name = new.target.name;
  }
}

export class CartNotFoundError extends DomainError {
  constructor(cartId: string) {
    super(`No existe el carrito '${cartId}'`, 'CART_NOT_FOUND', 404, { cartId });
  }
}

export class ProductNotFoundError extends DomainError {
  constructor(productId: string) {
    super(`No existe el producto '${productId}'`, 'PRODUCT_NOT_FOUND', 404, { productId });
  }
}

export class CartItemNotFoundError extends DomainError {
  constructor(productId: string) {
    super(`El producto '${productId}' no está en el carrito`, 'CART_ITEM_NOT_FOUND', 404, {
      productId,
    });
  }
}

export class InvalidQuantityError extends DomainError {
  constructor(quantity: unknown, max: number) {
    super(`La cantidad debe ser un entero entre 1 y ${max}`, 'INVALID_QUANTITY', 400, {
      quantity,
      max,
    });
  }
}

export class OutOfStockError extends DomainError {
  constructor(productId: string, requested: number, available: number) {
    super(
      `Stock insuficiente del producto '${productId}': solicitadas ${requested}, disponibles ${available}`,
      'OUT_OF_STOCK',
      409,
      { productId, requested, available },
    );
  }
}

export class InvalidDiscountCodeError extends DomainError {
  constructor(code: string) {
    super(`El código '${code}' no es válido`, 'INVALID_DISCOUNT_CODE', 422, { code });
  }
}

export class DiscountMinSubtotalError extends DomainError {
  constructor(code: string, requiredCents: number, currentCents: number) {
    super(
      `El código '${code}' requiere una compra mínima de ${(requiredCents / 100)
        .toFixed(2)
        .replace('.', ',')} €`,
      'DISCOUNT_MIN_SUBTOTAL',
      422,
      { code, requiredCents, currentCents },
    );
  }
}

export class EmptyCartError extends DomainError {
  constructor() {
    super('El carrito está vacío', 'EMPTY_CART', 409);
  }
}

/** Validación de forma de la petición en la capa HTTP (tipos, campos…). */
export class RequestValidationError extends DomainError {
  constructor(message: string, details?: unknown) {
    super(message, 'INVALID_REQUEST', 400, details);
  }
}

import type { Cart } from '../domain/cart.js';
import type { Product } from '../domain/product.js';

/**
 * PUERTOS de persistencia (arquitectura hexagonal).
 *
 * Los servicios dependen de estas INTERFACES, nunca de una base de datos
 * concreta. Sustituir SQLite por PostgreSQL, Redis o una API externa es
 * simplemente escribir otro adaptador: el resto del código no cambia.
 *
 * Son asíncronos a propósito: el adaptador SQLite es síncrono por debajo, pero
 * así un adaptador de red (p. ej. un microservicio de catálogo) cae sin tocar
 * los servicios ni las rutas.
 */
export interface CartRepository {
  create(cart: Cart): Promise<void>;
  findById(id: string): Promise<Cart | null>;
  /** Guarda el agregado completo (upsert del carrito y sus líneas). */
  save(cart: Cart): Promise<void>;
  delete(id: string): Promise<void>;
}

export interface ProductRepository {
  findAll(): Promise<Product[]>;
  findById(id: string): Promise<Product | null>;
  /**
   * Ajusta el stock de forma atómica (`stock += delta`).
   * Devuelve `false` si el producto no existe o si el resultado sería negativo.
   */
  adjustStock(productId: string, delta: number): Promise<boolean>;
}

import type { CartItemView, CartSummary } from '../domain/cart.js';

/**
 * Estrategia de descuento. Añadir un tipo nuevo ("envío gratis", "2x1", …)
 * es ampliar este union y su manejo en `price()`, sin tocar nada más.
 */
export interface DiscountRule {
  code: string;
  type: 'percent' | 'fixed';
  /** % (para 'percent') o céntimos (para 'fixed'). */
  value: number;
  /** Compra mínima en céntimos para poder aplicarlo. */
  minSubtotalCents?: number;
}

export interface PricingConfig {
  /** Impuesto sobre el importe gravable (0.21 = IVA del 21 %). */
  taxRate: number;
  shippingCents: number;
  freeShippingThresholdCents: number;
  /** Códigos activos, indexados en MAYÚSCULAS. */
  discounts: Record<string, DiscountRule>;
}

/**
 * Todas las reglas de precio del sistema viven aquí: una sola fuente de verdad.
 * Todos los importes son céntimos enteros y se redondea una vez por concepto,
 * de modo que la suma del desglose siempre cuadra exactamente.
 */
export class PricingService {
  constructor(private readonly config: PricingConfig) {}

  /** Busca el código tal cual se escribe; normaliza espacios y mayúsculas. */
  findDiscount(code: string): DiscountRule | null {
    return this.config.discounts[code.trim().toUpperCase()] ?? null;
  }

  price(items: CartItemView[], discountCode: string | null): CartSummary {
    const subtotalCents = items.reduce((sum, item) => sum + item.lineTotalCents, 0);

    // Se re-evalúa en cada lectura: si el carrito baja del mínimo, el código
    // deja de aplicarse (con discountCents = 0 y discountCode = null).
    let discountCents = 0;
    let appliedCode: string | null = null;
    const rule = discountCode ? this.findDiscount(discountCode) : null;
    if (rule && subtotalCents >= (rule.minSubtotalCents ?? 0)) {
      discountCents =
        rule.type === 'percent'
          ? Math.round((subtotalCents * rule.value) / 100)
          : Math.min(rule.value, subtotalCents);
      appliedCode = rule.code;
    }

    const taxableBase = subtotalCents - discountCents;
    const shippingCents =
      subtotalCents === 0 || taxableBase >= this.config.freeShippingThresholdCents
        ? 0
        : this.config.shippingCents;

    const taxCents = Math.round((taxableBase + shippingCents) * this.config.taxRate);
    const totalCents = taxableBase + shippingCents + taxCents;

    return {
      subtotalCents,
      discountCode: appliedCode,
      discountCents,
      taxRate: this.config.taxRate,
      taxCents,
      shippingCents,
      totalCents,
    };
  }
}

import { randomUUID } from 'node:crypto';
import { MAX_QTY_PER_ITEM, type Cart, type CartItemView, type CartView } from '../domain/cart.js';
import type { Product } from '../domain/product.js';
import {
  CartItemNotFoundError,
  CartNotFoundError,
  DiscountMinSubtotalError,
  EmptyCartError,
  InvalidDiscountCodeError,
  InvalidQuantityError,
  OutOfStockError,
  ProductNotFoundError,
} from '../domain/errors.js';
import type { CartRepository, ProductRepository } from '../ports/repositories.js';
import type { PricingService } from './pricing-service.js';

export interface CheckoutResult {
  order: {
    id: string;
    createdAt: string;
    itemCount: number;
    totalCents: number;
  };
  /** El carrito, ya vacío, para seguir comprando. */
  cart: CartView;
}

/**
 * Casos de uso del carrito. No sabe nada de HTTP ni de SQL: solo dominio,
 * puertos y pricing. Se prueba entero con repositorios en memoria (tests/).
 */
export class CartService {
  constructor(
    private readonly carts: CartRepository,
    private readonly products: ProductRepository,
    private readonly pricing: PricingService,
  ) {}

  async createCart(): Promise<CartView> {
    const now = new Date().toISOString();
    const cart: Cart = {
      id: `c_${randomUUID()}`,
      items: [],
      discountCode: null,
      createdAt: now,
      updatedAt: now,
    };
    await this.carts.create(cart);
    return this.buildView(cart);
  }

  async getCart(cartId: string): Promise<CartView> {
    return this.buildView(await this.mustGetCart(cartId));
  }

  /** Añade `quantity` unidades; si el producto ya está, las suma a la línea. */
  async addItem(cartId: string, productId: string, quantity: number): Promise<CartView> {
    this.assertQuantity(quantity);
    const cart = await this.mustGetCart(cartId);
    const product = await this.mustGetProduct(productId);
    const current = cart.items.find((item) => item.productId === productId)?.quantity ?? 0;
    const target = current + quantity;
    const limit = Math.min(product.stock, MAX_QTY_PER_ITEM);
    if (target > limit) {
      throw new OutOfStockError(product.id, target, limit);
    }
    return this.upsertAndSave(cart, productId, target);
  }

  /** Fija la cantidad de una línea. `quantity = 0` elimina la línea. */
  async setQuantity(cartId: string, productId: string, quantity: number): Promise<CartView> {
    if (quantity === 0) return this.removeItem(cartId, productId);
    this.assertQuantity(quantity);
    const cart = await this.mustGetCart(cartId);
    if (!cart.items.some((item) => item.productId === productId)) {
      throw new CartItemNotFoundError(productId);
    }
    const product = await this.mustGetProduct(productId);
    if (quantity > product.stock) {
      throw new OutOfStockError(product.id, quantity, product.stock);
    }
    return this.upsertAndSave(cart, productId, quantity);
  }

  async removeItem(cartId: string, productId: string): Promise<CartView> {
    const cart = await this.mustGetCart(cartId);
    const before = cart.items.length;
    cart.items = cart.items.filter((item) => item.productId !== productId);
    if (cart.items.length === before) throw new CartItemNotFoundError(productId);
    return this.save(cart);
  }

  /** Vacía el carrito manteniendo su identidad (el cliente puede seguir comprando). */
  async clearCart(cartId: string): Promise<CartView> {
    const cart = await this.mustGetCart(cartId);
    cart.items = [];
    return this.save(cart);
  }

  async applyDiscount(cartId: string, code: string): Promise<CartView> {
    const cart = await this.mustGetCart(cartId);
    const rule = this.pricing.findDiscount(code);
    if (!rule) throw new InvalidDiscountCodeError(code);
    const { subtotalCents } = (await this.buildView(cart)).summary;
    const min = rule.minSubtotalCents ?? 0;
    if (subtotalCents < min) throw new DiscountMinSubtotalError(rule.code, min, subtotalCents);
    cart.discountCode = rule.code;
    return this.save(cart);
  }

  async removeDiscount(cartId: string): Promise<CartView> {
    const cart = await this.mustGetCart(cartId);
    cart.discountCode = null;
    return this.save(cart);
  }

  /**
   * Checkout: re-valida el stock, lo descuenta, vacía el carrito y devuelve el
   * resumen del pedido. Si algo falla a mitad de camino, compensa los descuentos
   * ya aplicados (el siguiente paso natural sería una unidad de trabajo /
   * transacción: ver README → "Cómo extender").
   */
  async checkout(cartId: string): Promise<CheckoutResult> {
    const cart = await this.mustGetCart(cartId);
    if (cart.items.length === 0) throw new EmptyCartError();

    const snapshot = await this.buildView(cart);

    const decremented: { productId: string; quantity: number }[] = [];
    for (const item of cart.items) {
      const ok = await this.products.adjustStock(item.productId, -item.quantity);
      if (!ok) {
        for (const done of decremented) {
          await this.products.adjustStock(done.productId, done.quantity);
        }
        const product = await this.products.findById(item.productId);
        if (!product) throw new ProductNotFoundError(item.productId);
        throw new OutOfStockError(product.id, item.quantity, product.stock);
      }
      decremented.push(item);
    }

    cart.items = [];
    cart.discountCode = null;
    const view = await this.save(cart);

    return {
      order: {
        id: `o_${randomUUID()}`,
        createdAt: new Date().toISOString(),
        itemCount: snapshot.itemCount,
        totalCents: snapshot.summary.totalCents,
      },
      cart: view,
    };
  }

  private assertQuantity(quantity: number): void {
    if (!Number.isInteger(quantity) || quantity < 1 || quantity > MAX_QTY_PER_ITEM) {
      throw new InvalidQuantityError(quantity, MAX_QTY_PER_ITEM);
    }
  }

  private async mustGetCart(cartId: string): Promise<Cart> {
    const cart = await this.carts.findById(cartId);
    if (!cart) throw new CartNotFoundError(cartId);
    return cart;
  }

  private async mustGetProduct(productId: string): Promise<Product> {
    const product = await this.products.findById(productId);
    if (!product) throw new ProductNotFoundError(productId);
    return product;
  }

  private async upsertAndSave(
    cart: Cart,
    productId: string,
    quantity: number,
  ): Promise<CartView> {
    const existing = cart.items.find((item) => item.productId === productId);
    if (existing) {
      existing.quantity = quantity;
    } else {
      cart.items.push({ productId, quantity });
    }
    return this.save(cart);
  }

  private async save(cart: Cart): Promise<CartView> {
    cart.updatedAt = new Date().toISOString();
    await this.carts.save(cart);
    return this.buildView(cart);
  }

  /**
   * Enriquece las líneas con datos del catálogo y calcula el desglose.
   * Los precios SIEMPRE son los vigentes; el carrito no almacena precios.
   */
  private async buildView(cart: Cart): Promise<CartView> {
    const items: CartItemView[] = [];
    for (const item of cart.items) {
      const product = await this.products.findById(item.productId);
      if (!product) continue; // producto retirado del catálogo: no se muestra
      items.push({
        productId: product.id,
        name: product.name,
        emoji: product.emoji,
        unitPriceCents: product.priceCents,
        quantity: item.quantity,
        lineTotalCents: product.priceCents * item.quantity,
        stock: product.stock,
      });
    }
    const summary = this.pricing.price(items, cart.discountCode);
    return {
      id: cart.id,
      itemCount: items.reduce((sum, item) => sum + item.quantity, 0),
      items,
      summary,
    };
  }
}

import type { DiscountRule, PricingConfig } from './services/pricing-service.js';

export interface AppConfig {
  port: number;
  storage: 'sqlite' | 'memory';
  dbFile: string;
  pricing: PricingConfig;
}

function toInt(value: string | undefined, fallback: number): number {
  if (value === undefined || value.trim() === '') return fallback;
  const parsed = Number.parseInt(value, 10);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function toNumber(value: string | undefined, fallback: number): number {
  if (value === undefined || value.trim() === '') return fallback;
  const parsed = Number.parseFloat(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

const DEFAULT_DISCOUNTS: Record<string, DiscountRule> = {
  BIENVENIDA10: { code: 'BIENVENIDA10', type: 'percent', value: 10 },
  GASTA50: { code: 'GASTA50', type: 'percent', value: 5, minSubtotalCents: 5000 },
  CINCOEUROS: { code: 'CINCOEUROS', type: 'fixed', value: 500 },
};

/**
 * Configuración desde variables de entorno, con valores por defecto sensatos.
 * Cualquier valor no presente cae en el default: desplegar en otro entorno es
 * solo cuestión de variables, no de cambios de código.
 */
export function loadConfig(env: NodeJS.ProcessEnv = process.env): AppConfig {
  const storage = env.STORAGE === 'memory' ? 'memory' : 'sqlite';

  let discounts = DEFAULT_DISCOUNTS;
  if (env.DISCOUNT_CODES?.trim()) {
    try {
      const parsed = JSON.parse(env.DISCOUNT_CODES) as Record<string, Omit<DiscountRule, 'code'>>;
      discounts = Object.fromEntries(
        Object.entries(parsed).map(([code, rule]) => [
          code.toUpperCase(),
          { ...rule, code: code.toUpperCase() },
        ]),
      );
    } catch {
      console.warn('[config] DISCOUNT_CODES no es JSON válido; se usan los códigos por defecto');
    }
  }

  return {
    port: toInt(env.PORT, 3000),
    storage,
    dbFile: env.DB_FILE ?? 'data/cart.db',
    pricing: {
      // Impuesto acotado a [0, 1] por si acaso alguien escribe "21" en lugar de "0.21".
      taxRate: Math.min(Math.max(toNumber(env.TAX_RATE, 0.21), 0), 1),
      shippingCents: toInt(env.SHIPPING_CENTS, 499),
      freeShippingThresholdCents: toInt(env.FREE_SHIPPING_THRESHOLD_CENTS, 5000),
      discounts,
    },
  };
}

