import type { Product } from '../../domain/product.js';
import type { ProductRepository } from '../../ports/repositories.js';

/** Adaptador en memoria del puerto ProductRepository. */
export class MemoryProductRepository implements ProductRepository {
  private readonly products = new Map<string, Product>();

  constructor(catalog: Product[]) {
    for (const product of catalog) {
      this.products.set(product.id, { ...product });
    }
  }

  async findAll(): Promise<Product[]> {
    return [...this.products.values()]
      .map((product) => ({ ...product }))
      .sort((a, b) => a.name.localeCompare(b.name));
  }

  async findById(id: string): Promise<Product | null> {
    const product = this.products.get(id);
    return product ? { ...product } : null;
  }

  async adjustStock(productId: string, delta: number): Promise<boolean> {
    const product = this.products.get(productId);
    if (!product || product.stock + delta < 0) return false;
    product.stock += delta;
    return true;
  }
}

import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { DatabaseSync } from 'node:sqlite';

/**
 * Abre (o crea) la base de datos SQLite nativa de Node (node:sqlite, sin
 * dependencias nativas que compilar) y garantiza el esquema. Cambiar a
 * PostgreSQL u otra BD no toca este archivo: se escribe un adaptador nuevo
 * para los puertos (src/ports/repositories.ts).
 */
export function openDatabase(file: string): DatabaseSync {
  if (file !== ':memory:') {
    mkdirSync(dirname(file), { recursive: true });
  }

  const db = new DatabaseSync(file);
  db.exec('PRAGMA foreign_keys = ON');
  db.exec(`
    CREATE TABLE IF NOT EXISTS carts (
      id            TEXT PRIMARY KEY,
      discount_code TEXT,
      created_at    TEXT NOT NULL,
      updated_at    TEXT NOT NULL
    );

    CREATE TABLE IF NOT EXISTS cart_items (
      cart_id    TEXT NOT NULL REFERENCES carts(id) ON DELETE CASCADE,
      product_id TEXT NOT NULL,
      quantity   INTEGER NOT NULL CHECK (quantity > 0),
      PRIMARY KEY (cart_id, product_id)
    );

    CREATE TABLE IF NOT EXISTS products (
      id          TEXT PRIMARY KEY,
      name        TEXT NOT NULL,
      description TEXT NOT NULL,
      price_cents INTEGER NOT NULL CHECK (price_cents >= 0),
      currency    TEXT NOT NULL DEFAULT 'EUR',
      stock       INTEGER NOT NULL CHECK (stock >= 0),
      category    TEXT NOT NULL,
      emoji       TEXT NOT NULL
    );
  `);
  return db;
}

import type { DatabaseSync } from 'node:sqlite';
import type { Cart } from '../../domain/cart.js';
import type { CartRepository } from '../../ports/repositories.js';

interface CartRow {
  id: string;
  discount_code: string | null;
  created_at: string;
  updated_at: string;
}

interface ItemRow {
  product_id: string;
  quantity: number;
}

/**
 * Adaptador SQLite del puerto CartRepository.
 *
 * El agregado se guarda SIEMPRE completo (upsert del carrito + reescritura de
 * sus líneas dentro de una transacción): el mapeo es trivial y no hay estados
 * intermedios raros.
 */
export class SqliteCartRepository implements CartRepository {
  constructor(private readonly db: DatabaseSync) {}

  async create(cart: Cart): Promise<void> {
    this.db
      .prepare('INSERT INTO carts (id, discount_code, created_at, updated_at) VALUES (?, ?, ?, ?)')
      .run(cart.id, cart.discountCode, cart.createdAt, cart.updatedAt);
    this.insertItems(cart);
  }

  async findById(id: string): Promise<Cart | null> {
    const row = this.db
      .prepare('SELECT id, discount_code, created_at, updated_at FROM carts WHERE id = ?')
      .get(id) as CartRow | undefined;
    if (!row) return null;

    const items = this.db
      .prepare('SELECT product_id, quantity FROM cart_items WHERE cart_id = ? ORDER BY rowid')
      .all(id) as ItemRow[];

    return {
      id: row.id,
      discountCode: row.discount_code,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
      items: items.map((item) => ({ productId: item.product_id, quantity: item.quantity })),
    };
  }

  async save(cart: Cart): Promise<void> {
    this.db.exec('BEGIN');
    try {
      this.db
        .prepare(`
          INSERT INTO carts (id, discount_code, created_at, updated_at) VALUES (?, ?, ?, ?)
          ON CONFLICT(id) DO UPDATE
            SET discount_code = excluded.discount_code,
                updated_at   = excluded.updated_at
        `)
        .run(cart.id, cart.discountCode, cart.createdAt, cart.updatedAt);
      this.db.prepare('DELETE FROM cart_items WHERE cart_id = ?').run(cart.id);
      this.insertItems(cart);
      this.db.exec('COMMIT');
    } catch (error) {
      this.db.exec('ROLLBACK');
      throw error;
    }
  }

  async delete(id: string): Promise<void> {
    this.db.prepare('DELETE FROM carts WHERE id = ?').run(id);
  }

  private insertItems(cart: Cart): void {
    const stmt = this.db.prepare(
      'INSERT INTO cart_items (cart_id, product_id, quantity) VALUES (?, ?, ?)',
    );
    for (const item of cart.items) {
      stmt.run(cart.id, item.productId, item.quantity);
    }
  }
}

import type { DatabaseSync } from 'node:sqlite';
import type { Product } from '../../domain/product.js';
import type { ProductRepository } from '../../ports/repositories.js';

interface ProductRow {
  id: string;
  name: string;
  description: string;
  price_cents: number;
  currency: string;
  stock: number;
  category: string;
  emoji: string;
}

const SELECT_ALL =
  'SELECT id, name, description, price_cents, currency, stock, category, emoji FROM products';

/** Adaptador SQLite del puerto ProductRepository. */
export class SqliteProductRepository implements ProductRepository {
  constructor(private readonly db: DatabaseSync, catalog: Product[]) {
    // Siembra idempotente: INSERT OR IGNORE conserva el stock entre reinicios.
    const stmt = this.db.prepare(`
      INSERT OR IGNORE INTO products (id, name, description, price_cents, currency, stock, category, emoji)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `);
    for (const product of catalog) {
      stmt.run(
        product.id,
        product.name,
        product.description,
        product.priceCents,
        product.currency,
        product.stock,
        product.category,
        product.emoji,
      );
    }
  }

  async findAll(): Promise<Product[]> {
    const rows = this.db.prepare(`${SELECT_ALL} ORDER BY name`).all() as ProductRow[];
    return rows.map(rowToProduct);
  }

  async findById(id: string): Promise<Product | null> {
    const row = this.db.prepare(`${SELECT_ALL} WHERE id = ?`).get(id) as ProductRow | undefined;
    return row ? rowToProduct(row) : null;
  }

  async adjustStock(productId: string, delta: number): Promise<boolean> {
    // Atómico: solo toca la fila si el stock resultante no es negativo.
    const result = this.db
      .prepare('UPDATE products SET stock = stock + ? WHERE id = ? AND stock + ? >= 0')
      .run(delta, productId, delta);
    return Number(result.changes) > 0;
  }
}

function rowToProduct(row: ProductRow): Product {
  return {
    id: row.id,
    name: row.name,
    description: row.description,
    priceCents: row.price_cents,
    currency: row.currency,
    stock: row.stock,
    category: row.category,
    emoji: row.emoji,
  };
}

import type { NextFunction, Request, RequestHandler, Response } from 'express';
import { DomainError } from '../../domain/errors.js';

type AsyncHandler = (req: Request, res: Response, next: NextFunction) => Promise<unknown>;

/**
 * Envuelve handlers async para que sus errores lleguen al errorHandler.
 * (Express 5 ya lo hace solo, pero así funciona igual con cualquier versión.)
 */
export const asyncHandler =
  (fn: AsyncHandler): RequestHandler =>
  (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };

/** 404 para rutas no mapeadas. */
export const notFoundHandler: RequestHandler = (req, res) => {
  res.status(404).json({
    error: { code: 'ROUTE_NOT_FOUND', message: `Ruta no encontrada: ${req.method} ${req.path}` },
  });
};

/**
 * ÚNICO punto de traducción error → respuesta HTTP.
 * Los errores de dominio conocidos conservan su código y su estado; cualquier
 * otro error se trata como interno y se registra en el servidor, sin filtrar
 * detalles de la implementación al cliente.
 */
export const errorHandler = (
  err: unknown,
  _req: Request,
  res: Response,
  _next: NextFunction,
): void => {
  if (err instanceof DomainError) {
    res.status(err.httpStatus).json({
      error: { code: err.code, message: err.message, details: err.details ?? null },
    });
    return;
  }
  console.error('[http] error no controlado:', err);
  res.status(500).json({ error: { code: 'INTERNAL_ERROR', message: 'Error interno del servidor' } });
};

import { Router } from 'express';
import { ProductNotFoundError } from '../../domain/errors.js';
import type { ProductRepository } from '../../ports/repositories.js';
import { asyncHandler } from '../middleware/error-handler.js';

export interface ProductRoutesDeps {
  products: ProductRepository;
}

/** Endpoints de catálogo. Thin controllers: solo parsean y delegan. */
export function productRoutes(deps: ProductRoutesDeps): Router {
  const router = Router();

  router.get(
    '/',
    asyncHandler(async (_req, res) => {
      res.json({ products: await deps.products.findAll() });
    }),
  );

  router.get(
    '/:id',
    asyncHandler(async (req, res) => {
      const product = await deps.products.findById(req.params.id);
      if (!product) throw new ProductNotFoundError(req.params.id);
      res.json({ product });
    }),
  );

  return router;
}

import { Router } from 'express';
import { MAX_QTY_PER_ITEM } from '../../domain/cart.js';
import { RequestValidationError } from '../../domain/errors.js';
import type { CartService } from '../../services/cart-service.js';
import { asyncHandler } from '../middleware/error-handler.js';

export interface CartRoutesDeps {
  cartService: CartService;
}

function requireProductId(body: unknown): string {
  const { productId } = (body ?? {}) as Record<string, unknown>;
  if (typeof productId !== 'string' || productId.trim() === '') {
    throw new RequestValidationError("Se requiere 'productId' (string no vacío)");
  }
  return productId.trim();
}

function parseQuantity(body: unknown, { required }: { required: boolean }): number {
  const { quantity } = (body ?? {}) as Record<string, unknown>;
  if (quantity === undefined && !required) return 1;
  if (
    typeof quantity !== 'number' ||
    !Number.isSafeInteger(quantity) ||
    quantity < 0 ||
    quantity > MAX_QTY_PER_ITEM
  ) {
    throw new RequestValidationError(
      `'quantity' debe ser un entero entre 0 y ${MAX_QTY_PER_ITEM}`,
    );
  }
  return quantity;
}

/**
 * Endpoints del carrito. Validan la FORMA de la petición (transporte) y
 * delegan las reglas de negocio al servicio: nunca razonan sobre precios.
 */
export function cartRoutes(deps: CartRoutesDeps): Router {
  const { cartService } = deps;
  const router = Router();

  router.post(
    '/',
    asyncHandler(async (_req, res) => {
      const cart = await cartService.createCart();
      res.status(201).set('Location', `/api/carts/${cart.id}`).json(cart);
    }),
  );

  router.get(
    '/:cartId',
    asyncHandler(async (req, res) => {
      res.json(await cartService.getCart(req.params.cartId));
    }),
  );

  router.post(
    '/:cartId/items',
    asyncHandler(async (req, res) => {
      const productId = requireProductId(req.body);
      const quantity = parseQuantity(req.body, { required: false });
      res.status(201).json(await cartService.addItem(req.params.cartId, productId, quantity));
    }),
  );

  router.patch(
    '/:cartId/items/:productId',
    asyncHandler(async (req, res) => {
      const quantity = parseQuantity(req.body, { required: true });
      res.json(await cartService.setQuantity(req.params.cartId, req.params.productId, quantity));
    }),
  );

  router.delete(
    '/:cartId/items/:productId',
    asyncHandler(async (req, res) => {
      res.json(await cartService.removeItem(req.params.cartId, req.params.productId));
    }),
  );

  /** Vacía el contenido del carrito manteniendo su identidad. */
  router.delete(
    '/:cartId',
    asyncHandler(async (req, res) => {
      res.json(await cartService.clearCart(req.params.cartId));
    }),
  );

  router.post(
    '/:cartId/discount',
    asyncHandler(async (req, res) => {
      const { code } = (req.body ?? {}) as Record<string, unknown>;
      if (typeof code !== 'string' || code.trim() === '') {
        throw new RequestValidationError("Se requiere 'code' (string no vacío)");
      }
      res.json(await cartService.applyDiscount(req.params.cartId, code.trim()));
    }),
  );

  router.delete(
    '/:cartId/discount',
    asyncHandler(async (req, res) => {
      res.json(await cartService.removeDiscount(req.params.cartId));
    }),
  );

  router.post(
    '/:cartId/checkout',
    asyncHandler(async (req, res) => {
      res.status(201).json(await cartService.checkout(req.params.cartId));
    }),
  );

  return router;
}

import path from 'node:path';
import { fileURLToPath } from 'node:url';
import express, { type Express } from 'express';
import type { ProductRepository } from '../ports/repositories.js';
import type { CartService } from '../services/cart-service.js';
import { errorHandler, notFoundHandler } from './middleware/error-handler.js';
import { cartRoutes, type CartRoutesDeps } from './routes/cart-routes.js';
import { productRoutes } from './routes/product-routes.js';

export interface AppDeps extends CartRoutesDeps {
  products: ProductRepository;
}

// src/http/app.ts → ../../public (funciona igual compilado en dist/http/).
const publicDir = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', '..', 'public');

/**
 * Fábrica de la aplicación Express. Recibe las dependencias ya construidas
 * (inyección), lo que permite montarla en tests o detrás de un proxy sin
 * tocar el resto del código.
 */
export function createApp(deps: AppDeps): Express {
  const app = express();

  app.disable('x-powered-by');
  app.use(express.json({ limit: '64kb' }));

  // UI de demostración (archivos estáticos, sin build de frontend).
  app.use(express.static(publicDir));

  app.use('/api/products', productRoutes({ products: deps.products }));
  app.use('/api/carts', cartRoutes({ cartService: deps.cartService }));

  app.use(notFoundHandler);
  app.use(errorHandler);

  return app;
}

import { MemoryCartRepository } from './adapters/memory/memory-cart-repository.js';
import { MemoryProductRepository } from './adapters/memory/memory-product-repository.js';
import { SqliteCartRepository } from './adapters/sqlite/sqlite-cart-repository.js';
import { SqliteProductRepository } from './adapters/sqlite/sqlite-product-repository.js';
import { openDatabase } from './adapters/sqlite/db.js';
import { CATALOG } from './catalog.js';
import { loadConfig } from './config.js';
import { createApp } from './http/app.js';
import type { CartRepository, ProductRepository } from './ports/repositories.js';
import { CartService } from './services/cart-service.js';
import { PricingService } from './services/pricing-service.js';

async function bootstrap(): Promise<void> {
  const config = loadConfig();
  const pricing = new PricingService(config.pricing);

  // La elección del adaptador de persistencia vive en UN único sitio.
  let cartRepository: CartRepository;
  let productRepository: ProductRepository;
  let closeDatabase: (() => void) | undefined;

  if (config.storage === 'sqlite') {
    const db = openDatabase(config.dbFile);
    cartRepository = new SqliteCartRepository(db);
    productRepository = new SqliteProductRepository(db, CATALOG);
    closeDatabase = () => db.close();
  } else {
    cartRepository = new MemoryCartRepository();
    productRepository = new MemoryProductRepository(CATALOG);
    console.warn('[bootstrap] STORAGE=memory: los datos se pierden al reiniciar');
  }

  const cartService = new CartService(cartRepository, productRepository, pricing);
  const app = createApp({ cartService, products: productRepository });

  const server = app.listen(config.port, () => {
    console.log(
      `🛒 Carrito escuchando en http://localhost:${config.port} (storage: ${config.storage})`,
    );
  });

  const shutdown = (signal: string) => {
    console.log(`\n[shutdown] ${signal} recibido, cerrando…`);
    server.close(() => {
      closeDatabase?.();
      process.exit(0);
    });
  };
  process.on('SIGINT', () => shutdown('SIGINT'));
  process.on('SIGTERM', () => shutdown('SIGTERM'));
}

bootstrap().catch((error) => {
  console.error('Error arrancando el servidor:', error);
  process.exit(1);
});

